import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'contracts-store',
  description:
    "Read and update the vendor and contract desk (contracts.json and vendors.json). action:'status' for what needs deciding (notice dates and automatic renewals, missed ones first) and yearly spend; 'add' to save a contract (an existing id or title is updated, never duplicated; percentChange and monthlyChange adjust its price); 'renew' when one was renewed; 'cancel' when notice was given; 'set_status' to mark one under review, active again, or ended; 'add_vendor' to save a vendor; 'attach_file' to link a contract file under contract-files/; 'list' for every contract and vendor.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'status', 'add', 'renew', 'cancel', 'set_status', 'add_vendor', 'attach_file', or 'list'.",
      required: true,
    },
    id: { type: 'string', description: "Contract id, e.g. 'ct-3'." },
    title: {
      type: 'string',
      description: "The contract's name, e.g. 'Linen service'. Also finds it when no id is given.",
    },
    vendor: { type: 'string', description: 'The vendor or supplier, e.g. Bayside Linen. Also finds its contract.' },
    category: {
      type: 'string',
      description: 'food, supplies, linen, equipment, software, utilities, services, premises, insurance, or other.',
    },
    endAt: {
      type: 'string',
      description: 'When the current term ends, YYYY-MM-DD (for month-to-month, the next billing date). For renew: the new end date.',
    },
    autoRenew: { type: 'string', description: 'yes when it renews on its own unless notice is given, otherwise no.' },
    renewMonths: { type: 'number', description: 'Length of each term in months (default 12; 1 for month-to-month).' },
    noticeDays: { type: 'number', description: 'Days of notice needed before the end date to cancel or change it.' },
    annualCost: { type: 'number', description: 'What it costs a year, in dollars.' },
    monthlyCost: { type: 'number', description: 'What it costs a month, in dollars (kept as a yearly cost).' },
    percentChange: { type: 'number', description: 'A price change in percent: 6 for a 6% increase, -10 for a 10% cut.' },
    monthlyChange: { type: 'number', description: 'A price change in dollars a month: 40 for $40 more a month.' },
    owner: { type: 'string', description: 'Who looks after it.' },
    contact: { type: 'string', description: "For add_vendor: the vendor's contact, phone or email." },
    status: { type: 'string', description: 'For set_status: active, reviewing, or ended.' },
    note: { type: 'string', description: 'What happened, with any reference number exactly as written.' },
    file: { type: 'string', description: "Workspace path of a contract file, e.g. 'contract-files/linen-2026.pdf'." },
    withinDays: { type: 'number', description: 'How many days ahead counts as coming up (default 90).' },
  },
  outputs: {
    decisionsDue: { type: 'number', description: 'Contracts needing attention within the window.' },
    autoRenewWarnings: { type: 'number', description: 'Contracts that renew on their own whose notice date is near or already passed.' },
    annualSpend: { type: 'number', description: 'Yearly spend across live contracts, in dollars.' },
    contracts: { type: 'number', description: 'Contracts on the desk.' },
    summary: { type: 'string', description: 'The desk picture, or the listing.' },
  },
  requires: ['workspace.read', 'workspace.write', 'reminders'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── contracts-rules-start ──
// Pure derivations: a contract's current term end (one that renews on its own
// and passed its end date has renewed itself), its notice date, what it needs
// now, and the desk line the crew reads. Kept self-contained between these
// sentinels so unit tests execute the shipped bytes.
var DAY_MS = 86400000;
var WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
var MONTH_KEYS = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}
function localDay(ms) {
  var d = new Date(ms);
  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
}
function noon(day) {
  return new Date(String(day).slice(0, 10) + 'T12:00:00');
}
function addDays(day, n) {
  var d = noon(day);
  d.setDate(d.getDate() + n);
  return localDay(d.getTime());
}
function addMonths(day, months) {
  var d = noon(day);
  var date = d.getDate();
  d.setDate(1);
  d.setMonth(d.getMonth() + months);
  // The 31st rolls to the last day of a shorter month, not into the next one.
  d.setDate(Math.min(date, new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate()));
  return localDay(d.getTime());
}
function daysLeft(day, nowMs) {
  var due = Date.parse(String(day).slice(0, 10) + 'T00:00:00');
  var today = Date.parse(localDay(nowMs) + 'T00:00:00');
  return Math.round((due - today) / DAY_MS);
}
function dayName(day) {
  return WEEKDAYS[noon(day).getDay()];
}
function parseDay(text, nowMs, direction) {
  var raw = String(text == null ? '' : text).trim().toLowerCase().replace(/[.,]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!raw) return null;
  var iso = raw.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:t.*)?$/);
  if (iso) return iso[1] + '-' + pad(Number(iso[2])) + '-' + pad(Number(iso[3]));
  var today = localDay(nowMs);
  if (raw === 'today' || raw === 'now') return today;
  if (raw === 'tomorrow') return addDays(today, 1);
  if (raw === 'yesterday') return addDays(today, -1);
  var rel = raw.match(/^(?:in )?(\d{1,3}) (day|days|week|weeks)( ago| from now)?$/);
  if (rel) {
    var n = Number(rel[1]) * (rel[2].charAt(0) === 'w' ? 7 : 1);
    return addDays(today, rel[3] === ' ago' ? -n : n);
  }
  var wd = raw.match(/^(this |next |last |on |coming )?(sun|mon|tue|wed|thu|fri|sat)[a-z]*$/);
  if (wd) {
    var target = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'].indexOf(wd[2]);
    var now = noon(today).getDay();
    if (direction === 'past' || wd[1] === 'last ') {
      var back = (now - target + 7) % 7;
      return addDays(today, -(wd[1] === 'last ' && back === 0 ? 7 : back));
    }
    if (wd[1] === 'this ') return addDays(today, (target - now + 7) % 7);
    return addDays(today, ((target - now + 6) % 7) + 1);
  }
  var md = raw.match(/^(?:[a-z]+day )?([a-z]{3,9}) (\d{1,2})(?:st|nd|rd|th)?(?: (\d{4}))?$/);
  var dm = raw.match(/^(?:[a-z]+day )?(\d{1,2})(?:st|nd|rd|th)? (?:of )?([a-z]{3,9})(?: (\d{4}))?$/);
  var parts = md ? { month: md[1], date: md[2], year: md[3] } : dm ? { month: dm[2], date: dm[1], year: dm[3] } : null;
  if (parts) {
    var m = MONTH_KEYS.indexOf(parts.month.slice(0, 3));
    if (m < 0) return null;
    var date = Number(parts.date);
    if (date < 1 || date > 31) return null;
    if (parts.year) return parts.year + '-' + pad(m + 1) + '-' + pad(date);
    var year = noon(today).getFullYear();
    var guess = year + '-' + pad(m + 1) + '-' + pad(date);
    var d = daysLeft(guess, nowMs);
    if (direction === 'past' && d > 0) guess = year - 1 + guess.slice(4);
    if (direction !== 'past' && d < 0) guess = year + 1 + guess.slice(4);
    return guess;
  }
  return null;
}
function matches(records, text, labelOf) {
  var wanted = String(text == null ? '' : text).trim().toLowerCase().replace(/['\u2019]s\b/g, '').replace(/\s+/g, ' ');
  if (!wanted) return [];
  var tiers = [
    function (r) { return String(r.id).toLowerCase() === wanted; },
    function (r) { return labelOf(r).toLowerCase() === wanted; },
    function (r) { return labelOf(r).toLowerCase().indexOf(wanted) === 0; },
    function (r) { return (' ' + labelOf(r).toLowerCase() + ' ').indexOf(' ' + wanted + ' ') >= 0; },
    function (r) { return labelOf(r).toLowerCase().indexOf(wanted) >= 0; },
    function (r) { var l = labelOf(r).toLowerCase(); return l.length >= 3 && wanted.indexOf(l) >= 0; },
  ];
  for (var i = 0; i < tiers.length; i++) {
    var hit = records.filter(tiers[i]);
    if (hit.length) return hit;
  }
  return [];
}
function describe(records, labelOf) {
  return records.map(function (r) { return r.id + ' ' + labelOf(r); }).join(', ');
}
function splitList(text) {
  var raw = String(text == null ? '' : text).trim();
  if (/^\[/.test(raw)) {
    try {
      var parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) return parsed.map(function (s) { return String(s).trim(); }).filter(Boolean);
    } catch (e) {
      // Not JSON after all; split it as text.
    }
  }
  return raw
    .split(/\s*[,;\n]+\s*/)
    .map(function (s) { return s.replace(/^(and|or|plus)\s+/i, '').replace(/[.\s]+$/, '').trim(); })
    .filter(Boolean);
}
var CATEGORIES = ["food","supplies","linen","equipment","software","utilities","services","premises","insurance","other"];
var DEFAULT_NOTICE_DAYS = 30;
var FILLER = ['the', 'our', 'contract', 'contracts', 'agreement', 'with', 'for', 'and', 'from', 'deal'];

function yes(value) {
  return value === true || /^(yes|true|y|auto|automatic|automatically)$/i.test(String(value == null ? '' : value).trim());
}
function money(cents) {
  var n = Math.round(Number(cents) || 0);
  var sign = n < 0 ? '-' : '';
  n = Math.abs(n);
  var dollars = String(Math.floor(n / 100)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return sign + '$' + dollars + (n % 100 ? '.' + pad(n % 100) : '');
}
function inDays(days) {
  if (days < 0) return -days + (days === -1 ? ' day ago' : ' days ago');
  if (days === 0) return 'today';
  return 'in ' + days + (days === 1 ? ' day' : ' days');
}
function termMonths(f) {
  var m = Number(f.renewMonths);
  return m > 0 ? Math.round(m) : 12;
}
function noticeOf(f) {
  if (f.noticeDays === undefined || f.noticeDays === null || f.noticeDays === '') return null;
  var n = Number(f.noticeDays);
  return n >= 0 ? Math.round(n) : null;
}
// Rolled from the recorded date a whole number of terms at a time, so a 31st never drifts.
// A contract with notice given (fixed) ends on its recorded date.
function termEnd(f, nowMs, fixed) {
  if (!f.endAt) return null;
  var first = String(f.endAt).slice(0, 10);
  if (fixed || !yes(f.autoRenew)) return first;
  var end = first;
  for (var k = 1; k <= 600 && daysLeft(end, nowMs) < 0; k++) end = addMonths(first, k * termMonths(f));
  return end;
}
function view(record, nowMs) {
  var f = record.fields || {};
  var end = termEnd(f, nowMs, record.status === 'cancelling' || record.status === 'ended');
  var notice = noticeOf(f);
  var noticeBy = end ? addDays(end, -(notice === null ? DEFAULT_NOTICE_DAYS : notice)) : null;
  return {
    end: end,
    noticeBy: noticeBy,
    notice: notice,
    auto: yes(f.autoRenew),
    rolled: !!end && end !== String(f.endAt).slice(0, 10),
    toNotice: noticeBy ? daysLeft(noticeBy, nowMs) : null,
    toEnd: end ? daysLeft(end, nowMs) : null,
  };
}
// notice: renews on its own unless notice goes out by a date inside the window.
// locked: renews on its own and this term's notice date has passed.
// ending: a fixed term ends; decide inside the window. expired: it ended unrenewed.
function stateOf(record, nowMs, withinDays) {
  var v = view(record, nowMs);
  if (record.status === 'ended') return 'ended';
  if (!v.end) return 'undated';
  if (record.status === 'cancelling') return v.toEnd < 0 ? 'ended' : 'cancelling';
  if (v.auto) return v.toNotice < 0 ? 'locked' : v.toNotice <= withinDays ? 'notice' : 'later';
  if (v.toEnd < 0) return 'expired';
  return v.toNotice <= withinDays ? 'ending' : 'later';
}
function renewText(f) {
  var m = termMonths(f);
  return m === 1 ? 'for another month' : 'for another ' + m + ' months';
}
function costText(f) {
  return typeof f.annualCents === 'number' ? money(f.annualCents) + ' a year' : 'cost not recorded';
}
function line(record, nowMs, withinDays) {
  var f = record.fields || {};
  var v = view(record, nowMs);
  var s = stateOf(record, nowMs, withinDays);
  var assumed = v.notice === null ? ' (notice period not recorded; ' + DEFAULT_NOTICE_DAYS + ' days assumed)' : '';
  var what =
    s === 'ended' ? 'ended' + (v.end ? ' ' + v.end : '')
    : s === 'undated' ? 'no end date recorded'
    : s === 'cancelling' ? 'notice given; ends ' + v.end + ' (' + inDays(v.toEnd) + ')'
    : s === 'locked' ? 'its notice date ' + v.noticeBy + ' has passed, so it renews automatically on ' + v.end + ' (' + inDays(v.toEnd) + ') ' + renewText(f)
    : s === 'expired' ? 'ended ' + v.end + ' (' + inDays(v.toEnd) + ') and does not renew on its own: record a renewal or mark it ended'
    : v.auto ? 'give notice by ' + v.noticeBy + ' (' + inDays(v.toNotice) + ') or it renews automatically on ' + v.end + ' ' + renewText(f) + assumed
    : 'ends ' + v.end + ' (' + inDays(v.toEnd) + ') and does not renew on its own; decide by ' + v.noticeBy + ' (' + inDays(v.toNotice) + ')' + assumed;
  return (
    f.title + ' (' + record.id + ', ' + (f.vendor || 'no vendor') + (f.owner ? ', owner ' + f.owner : '') + '): ' + what +
    (record.status === 'reviewing' ? '; under review' : '') +
    '; ' + costText(f) +
    (f.file ? '; contract file ' + f.file : '')
  );
}
// Missed dates first (ended unrenewed, then too late to cancel), then the soonest date to act on.
function urgency(record, nowMs, withinDays) {
  var v = view(record, nowMs);
  var s = stateOf(record, nowMs, withinDays);
  if (s === 'expired') return -100000 + v.toEnd;
  if (s === 'locked') return -50000 + v.toEnd;
  return v.toNotice;
}
function picture(contracts, vendorCount, nowMs, withinDays) {
  var states = contracts.map(function (r) { return stateOf(r, nowMs, withinDays); });
  var pick = function (names) {
    return contracts.filter(function (r, i) { return names.indexOf(states[i]) >= 0; });
  };
  var live = contracts.filter(function (r, i) { return states[i] !== 'ended'; });
  var annual = live.reduce(function (sum, r) { return sum + (Number(r.fields && r.fields.annualCents) || 0); }, 0);
  var due = pick(['expired', 'locked', 'notice', 'ending']).sort(function (a, b) {
    return urgency(a, nowMs, withinDays) - urgency(b, nowMs, withinDays);
  });
  var warnings = pick(['locked', 'notice']).length;
  var parts = [
    live.length + ' live ' + (live.length === 1 ? 'contract' : 'contracts') + ' with ' + vendorCount + ' ' + (vendorCount === 1 ? 'vendor' : 'vendors') + ', ' + money(annual) + ' a year' + (warnings ? '; ' + warnings + (warnings === 1 ? ' renews on its own' : ' renew on their own') + ' soon' : '') + '.',
  ];
  // One list, missed dates first: a model asked what needs deciding reads one list, not side lists.
  parts.push(
    due.length
      ? 'Needing a decision within ' + withinDays + ' days, most urgent first: ' + due.map(function (r) { return line(r, nowMs, withinDays); }).join(' | ') + '.'
      : 'Nothing needs a decision in the next ' + withinDays + ' days.',
  );
  var cancelling = pick(['cancelling']);
  if (cancelling.length) parts.push('Notice already given: ' + cancelling.map(function (r) { return line(r, nowMs, withinDays); }).join(' | ') + '.');
  var undated = pick(['undated']);
  if (undated.length) parts.push('No end date recorded: ' + undated.map(function (r) { return r.fields.title + ' (' + r.id + ')'; }).join(', ') + '.');
  var later = pick(['later']).sort(function (a, b) { return view(a, nowMs).toNotice - view(b, nowMs).toNotice; });
  if (later.length) {
    var next = view(later[0], nowMs);
    parts.push('Next after that: ' + later[0].fields.title + ', ' + (next.auto ? 'give notice by ' : 'decide by ') + next.noticeBy + '.');
  }
  var spend = {};
  live.forEach(function (r) {
    var kind = (r.fields && r.fields.category) || 'other';
    spend[kind] = (spend[kind] || 0) + (Number(r.fields && r.fields.annualCents) || 0);
  });
  var kinds = Object.keys(spend).filter(function (k) { return spend[k] > 0; }).sort(function (a, b) { return spend[b] - spend[a]; });
  if (kinds.length) parts.push('Yearly spend by kind: ' + kinds.map(function (k) { return k + ' ' + money(spend[k]); }).join(', ') + '.');
  return { decisionsDue: due.length, autoRenewWarnings: warnings, annualCents: annual, summary: parts.join(' ') };
}
function contractLabel(r) {
  return String((r.fields && r.fields.title) || '');
}
// By id or title first, then the vendor's name, then every telling word of the request.
function findContracts(records, text) {
  var hit = matches(records, text, contractLabel);
  if (hit.length) return hit;
  hit = matches(records, text, function (r) { return String((r.fields && r.fields.vendor) || ''); });
  if (hit.length) return hit;
  var want = String(text == null ? '' : text).toLowerCase().split(/[^a-z0-9]+/).filter(function (w) {
    return w.length > 2 && FILLER.indexOf(w) < 0;
  });
  if (!want.length) return [];
  return records.filter(function (r) {
    var have = (contractLabel(r) + ' ' + String((r.fields && r.fields.vendor) || '')).toLowerCase().split(/[^a-z0-9]+/);
    return want.every(function (w) {
      var stem = w.replace(/s$/, '');
      return have.some(function (h) { return h.indexOf(stem) === 0; });
    });
  });
}
// ── contracts-rules-end ──

const contracts = rosterStore(gezel.fs, 'contracts.json', {
  stages: ['active', 'reviewing', 'cancelling', 'ended'],
  idPrefix: 'ct',
});
const vendors = rosterStore(gezel.fs, 'vendors.json', {
  stages: ['active', 'inactive'],
  idPrefix: 'vn',
});
type Contract = Awaited<ReturnType<typeof contracts.list>>[number];

const now = Date.now();
const today = localDay(now);
const withinDays = typeof input.withinDays === 'number' && input.withinDays > 0 ? Math.round(input.withinDays) : 90;
let note = '';

function clip(text: string, max: number): string {
  return text.length > max ? text.slice(0, max - 1) + '…' : text;
}
function known(all: Contract[]): string {
  return describe(all, contractLabel) || 'none yet';
}

async function resolveContract(): Promise<Contract> {
  const all = await contracts.list();
  const text = input.id || input.title || input.vendor;
  if (!text) throw new Error("Pass 'id' (e.g. 'ct-3') or the contract's 'title'. Contracts: " + known(all) + '.');
  const hits = findContracts(all, text);
  if (hits.length === 1) return hits[0]!;
  if (hits.length > 1) throw new Error("More than one contract matches '" + text + "': " + describe(hits, contractLabel) + '. Pass id.');
  throw new Error("No contract matches '" + text + "'. Contracts: " + known(all) + '.');
}

async function ensureVendor(name: string, category: string | undefined) {
  const wanted = name.trim().toLowerCase();
  const found = (await vendors.list()).find((v) => String(v.fields.name ?? '').toLowerCase() === wanted);
  if (found) return found;
  return vendors.add({ status: 'active', fields: { name: name.trim(), category: category ?? 'other' } });
}

function dollars(value: unknown): number | undefined {
  return typeof value === 'number' && isFinite(value) && value >= 0 ? Math.round(value * 100) : undefined;
}

// The yearly cost a call states or implies: a stated cost wins, then the relative changes apply.
function priced(current: unknown): { cents?: number; change: string } {
  const monthly = dollars(input.monthlyCost);
  const stated = dollars(input.annualCost) ?? (monthly === undefined ? undefined : monthly * 12);
  const relative = typeof input.percentChange === 'number' || typeof input.monthlyChange === 'number';
  if (!relative) return { cents: stated, change: '' };
  const base = stated ?? (typeof current === 'number' ? current : undefined);
  if (base === undefined) throw new Error('There is no recorded cost to change yet; pass annualCost or monthlyCost.');
  let next = base;
  if (typeof input.percentChange === 'number') next = Math.round(next * (1 + input.percentChange / 100));
  if (typeof input.monthlyChange === 'number') next += Math.round(input.monthlyChange * 100) * 12;
  next = Math.max(0, next);
  return { cents: next, change: 'price from ' + money(base) + ' to ' + money(next) + ' a year' };
}

// The desk's one reminder sits two weeks ahead of the soonest notice date (or a fixed term's end).
async function remindNextNotice(all: Contract[]): Promise<void> {
  const lead = 14 * DAY_MS;
  const next = all
    .filter((r) => r.status === 'active' || r.status === 'reviewing')
    .map((r) => {
      const v = view(r, now);
      const day = v.toNotice !== null && v.toNotice >= 0 ? v.noticeBy : !v.auto && v.toEnd !== null && v.toEnd >= 0 ? v.end : null;
      return { r, v, day, at: day ? Date.parse(day + 'T09:00:00') - lead : NaN };
    })
    .filter((x) => x.day && x.at > now)
    .sort((a, b) => a.at - b.at)[0];
  try {
    if (!next || next.at - now > 30 * DAY_MS) {
      await gezel.reminder.clear();
    } else {
      const title = String(next.r.fields.title);
      const onNotice = next.day === next.v.noticeBy;
      await gezel.reminder.set({
        at: new Date(next.at).toISOString(),
        title: clip(onNotice ? 'Notice on ' + title + ' is due in two weeks' : title + ' ends in two weeks', 80),
        body: clip(
          onNotice
            ? next.v.auto
              ? 'Give notice by ' + next.day + ' or it renews on ' + next.v.end + '. Open the contract desk to decide.'
              : 'Decide by ' + next.day + ' whether to renew; it ends ' + next.v.end + '.'
            : 'It ends ' + next.v.end + ' and does not renew on its own.',
          160,
        ),
      });
    }
  } catch {
    // Reminders are a convenience; the desk is the record.
  }
}

if (input.action === 'add') {
  const all = await contracts.list();
  const wanted = String(input.title ?? '').trim().toLowerCase();
  let existing = input.id
    ? all.find((r) => r.id === input.id)
    : all.find((r) => String(r.fields.title ?? '').toLowerCase() === wanted);
  if (input.id && !existing) throw new Error('No contract ' + input.id + '. Contracts: ' + known(all) + '.');
  const endAt = input.endAt ? parseDay(input.endAt, now, 'future') : null;
  if (input.endAt && !endAt) throw new Error("endAt must be a date, e.g. '2027-03-31'.");
  const relative = typeof input.percentChange === 'number' || typeof input.monthlyChange === 'number';
  // A call with no end date cannot start a contract, so a loose title names an existing one.
  if (!existing && wanted && (!endAt || relative)) {
    const loose = findContracts(all, input.title);
    if (loose.length === 1) existing = loose[0];
    else if (loose.length > 1) throw new Error("More than one contract matches '" + input.title + "': " + describe(loose, contractLabel) + '. Pass id.');
    else if (relative) throw new Error("No contract matches '" + input.title + "' to change its price. Contracts: " + known(all) + '.');
  }
  if (!existing && !wanted) throw new Error("add needs 'title'.");
  if (input.noticeDays !== undefined && !(Number(input.noticeDays) >= 0)) throw new Error('noticeDays must be zero or more.');
  const category = CATEGORIES.indexOf(String(input.category)) >= 0 ? String(input.category) : undefined;
  const vendor = input.vendor ? await ensureVendor(input.vendor, category) : null;
  const price = priced(existing ? existing.fields.annualCents : undefined);
  const fields: Record<string, unknown> = {
    ...(vendor ? { vendor: String(vendor.fields.name), vendorId: vendor.id } : {}),
    ...(category ? { category } : {}),
    ...(endAt ? { endAt } : {}),
    ...(input.autoRenew ? { autoRenew: yes(input.autoRenew) ? 'yes' : 'no' } : {}),
    ...(typeof input.renewMonths === 'number' && input.renewMonths > 0 ? { renewMonths: Math.round(input.renewMonths) } : {}),
    ...(typeof input.noticeDays === 'number' ? { noticeDays: Math.round(input.noticeDays) } : {}),
    ...(price.cents !== undefined ? { annualCents: price.cents } : {}),
    ...(input.owner ? { owner: input.owner.trim() } : {}),
    ...(input.note ? { notes: input.note.trim() } : {}),
  };
  if (existing) {
    await contracts.update(existing.id, { fields, ...(price.change ? { note: 'Price change: ' + price.change + '.' } : {}) });
    note = 'Updated ' + String(existing.fields.title) + (price.change ? ': ' + price.change : '') + '.';
  } else {
    if (!endAt) throw new Error("A new contract needs 'endAt': when its current term ends (YYYY-MM-DD; for month-to-month, the next billing date).");
    const record = await contracts.add({
      status: 'active',
      fields: {
        title: String(input.title).trim(),
        category: category ?? (vendor ? String(vendor.fields.category ?? 'other') : 'other'),
        autoRenew: 'no',
        ...fields,
      },
    });
    note = 'Added ' + record.id + ' ' + String(record.fields.title) + '.';
  }
} else if (input.action === 'renew') {
  const r = await resolveContract();
  const v = view(r, now);
  const months = typeof input.renewMonths === 'number' && input.renewMonths > 0 ? Math.round(input.renewMonths) : termMonths(r.fields);
  const nextEnd = input.endAt ? parseDay(input.endAt, now, 'future') : v.end ? addMonths(v.end, months) : null;
  if (input.endAt && !nextEnd) throw new Error("endAt must be a date, e.g. '2027-12-14'.");
  if (!nextEnd) throw new Error("renew needs 'endAt': the new end date.");
  const price = priced(r.fields.annualCents);
  const fields: Record<string, unknown> = {
    endAt: nextEnd,
    lastRenewedAt: today,
    ...(typeof input.renewMonths === 'number' && input.renewMonths > 0 ? { renewMonths: months } : {}),
    ...(price.cents !== undefined ? { annualCents: price.cents } : {}),
  };
  await contracts.update(r.id, { fields, note: input.note ?? 'Renewed through ' + nextEnd + '.' });
  if (r.status !== 'active') await contracts.transition(r.id, 'active', { note: 'Renewed.' });
  const after = view({ id: r.id, status: 'active', fields: { ...r.fields, ...fields } }, now);
  note =
    String(r.fields.title) + ' renewed through ' + nextEnd + (price.cents !== undefined ? ' at ' + money(price.cents) + ' a year' : '') +
    (after.auto ? '; next notice date ' + after.noticeBy : '') + '.';
} else if (input.action === 'cancel') {
  const r = await resolveContract();
  if (r.status === 'ended') throw new Error(String(r.fields.title) + ' has already ended.');
  const v = view(r, now);
  if (v.end && v.end !== r.fields.endAt) await contracts.update(r.id, { fields: { endAt: v.end } });
  await contracts.transition(r.id, 'cancelling', { note: input.note ?? 'Notice given.' });
  const late = v.auto && v.toNotice !== null && v.toNotice < 0;
  note =
    'Notice recorded for ' + String(r.fields.title) + (v.end ? '; it ends ' + v.end : '') + '.' +
    (late ? ' Its notice date ' + v.noticeBy + ' had already passed, so confirm with ' + String(r.fields.vendor || 'the vendor') + ' whether it renews for one more term first.' : '');
} else if (input.action === 'set_status') {
  if (['active', 'reviewing', 'ended'].indexOf(String(input.status)) < 0) throw new Error("set_status needs status 'active', 'reviewing' or 'ended'.");
  const r = await resolveContract();
  await contracts.transition(r.id, String(input.status), input.note ? { note: input.note } : {});
  note = String(r.fields.title) + (input.status === 'reviewing' ? ' is under review.' : input.status === 'ended' ? ' has ended.' : ' is active.');
} else if (input.action === 'add_vendor') {
  const name = String(input.vendor ?? input.title ?? '').trim();
  if (!name) throw new Error("add_vendor needs 'vendor': the vendor's name.");
  const category = CATEGORIES.indexOf(String(input.category)) >= 0 ? String(input.category) : undefined;
  const found = (await vendors.list()).find((v) => String(v.fields.name ?? '').toLowerCase() === name.toLowerCase());
  const fields: Record<string, unknown> = {
    ...(category ? { category } : {}),
    ...(input.contact ? { contact: input.contact.trim() } : {}),
    ...(input.note ? { notes: input.note.trim() } : {}),
  };
  if (found) {
    await vendors.update(found.id, { fields });
    note = 'Updated vendor ' + String(found.fields.name) + '.';
  } else {
    const v = await vendors.add({ status: 'active', fields: { name, category: category ?? 'other', ...fields } });
    note = 'Added vendor ' + v.id + ' ' + name + '.';
  }
} else if (input.action === 'attach_file') {
  const raw = String(input.file ?? '').trim().replace(/\\/g, '/').replace(/^\.?\/+/, '');
  if (!raw) throw new Error("attach_file needs 'file', e.g. 'contract-files/linen-2026.pdf'.");
  if (raw.split('/').indexOf('..') >= 0) throw new Error('file must be a path inside the workspace.');
  const file = raw.indexOf('/') < 0 ? 'contract-files/' + raw : raw;
  const r = await resolveContract();
  await contracts.update(r.id, { fields: { file }, note: 'Contract file: ' + file + '.' });
  note = 'Linked ' + file + ' to ' + String(r.fields.title) + '.';
} else if (input.action !== 'status' && input.action !== 'list') {
  throw new Error("Unknown action '" + input.action + "'. Use status, add, renew, cancel, set_status, add_vendor, attach_file, or list.");
}

const all = await contracts.list();
const vendorList = await vendors.list();
const desk = picture(all, vendorList.filter((v) => v.status === 'active').length, now, withinDays);
await remindNextNotice(all);

function vendorLine(v: (typeof vendorList)[number]): string {
  const name = String(v.fields.name ?? '');
  const own = all.filter(
    (r) => (r.fields.vendorId === v.id || String(r.fields.vendor ?? '').toLowerCase() === name.toLowerCase()) && stateOf(r, now, withinDays) !== 'ended',
  );
  const cents = own.reduce((sum, r) => sum + (Number(r.fields.annualCents) || 0), 0);
  return (
    name + ' (' + v.id + ', ' + String(v.fields.category ?? 'other') + (v.fields.contact ? ', contact ' + String(v.fields.contact) : '') + (v.status !== 'active' ? ', inactive' : '') + '): ' +
    (own.length ? own.length + (own.length === 1 ? ' contract, ' : ' contracts, ') + money(cents) + ' a year' : 'no contract on the desk')
  );
}

// Vendors without a contract (the electrician you call) are otherwise invisible to a status read.
const callOnly = vendorList.filter((v) => v.status === 'active' && vendorLine(v).endsWith('no contract on the desk')).slice(0, 8);
const extra = callOnly.length
  ? ' Vendors with no contract on the desk: ' +
    callOnly.map((v) => String(v.fields.name) + ' (' + String(v.fields.category ?? 'other') + (v.fields.contact ? ', ' + String(v.fields.contact) : '') + ')').join(', ') + '.'
  : '';

gezel.output({
  decisionsDue: desk.decisionsDue,
  autoRenewWarnings: desk.autoRenewWarnings,
  annualSpend: desk.annualCents / 100,
  contracts: all.length,
  summary:
    input.action === 'list'
      ? (all.map((r) => '[' + r.status + '] ' + line(r, now, withinDays)).join('\n') || 'No contracts yet.') +
        '\n\nVendors:\n' + (vendorList.map(vendorLine).join('\n') || 'none yet')
      : (note ? note + ' ' : '') + desk.summary + extra,
});

